-- Landlord Recruitment Database v0.2, generated by tools/landlord-db-import.mjs from the workbook (do not edit by hand; regenerate).
-- 41 landlord records, 0 properties, 17 channels, 10 business networks,
-- 24 property managers, 16 large networks, 47 sources. Outreach_Log example row not imported.
-- Office edits are kept: research columns change only where staff_edited_at is null and is_local is false.

on conflict (source_id) do update set title = excluded.title, url = excluded.url, source_type = excluded.source_type, import_version = excluded.import_version, imported_at = now();

on conflict (channel_id) do update set channel = excluded.channel, what_it_is = excluded.what_it_is, contact_access = excluded.contact_access, how_used = excluded.how_used, verification_status = excluded.verification_status, source_ids = excluded.source_ids, import_version = excluded.import_version, imported_at = now()
  where lrd_channels.staff_edited_at is null;

on conflict (network_id) do update set network = excluded.network, who_belongs = excluded.who_belongs, contact = excluded.contact, how_to_use = excluded.how_to_use, verification_status = excluded.verification_status, source_url = excluded.source_url, import_version = excluded.import_version, imported_at = now()
  where lrd_business_networks.staff_edited_at is null;

on conflict (landlord_id) do update set owner_or_company_name = excluded.owner_or_company_name, segment = excluded.segment, entity_type = excluded.entity_type, size_tier = excluded.size_tier, independent_flag = excluded.independent_flag, units_known = excluded.units_known, parcels_known = excluded.parcels_known, parcels_note = excluded.parcels_note, tax_bill_or_business_address = excluded.tax_bill_or_business_address, local_status = excluded.local_status, accepts_vouchers = excluded.accepts_vouchers, lift_member = excluded.lift_member, recruitment_channel = excluded.recruitment_channel, contact_status = case when lrd_landlords.claimed_by_navigator is null and lrd_landlords.nav_landlord_id is null and not lrd_landlords.do_not_contact
    and not exists (select 1 from lrd_outreach o where o.landlord_id = lrd_landlords.landlord_id) then excluded.contact_status else lrd_landlords.contact_status end, eviction_filings_per_100_units = excluded.eviction_filings_per_100_units, code_violations_per_100_units = excluded.code_violations_per_100_units, screening_result = excluded.screening_result, do_not_partner_flag = excluded.do_not_partner_flag, do_not_partner = excluded.do_not_partner, verification_status = excluded.verification_status, source_ids = excluded.source_ids, date_added = excluded.date_added, import_version = excluded.import_version, imported_at = now()
  where lrd_landlords.staff_edited_at is null and not lrd_landlords.is_local;

-- Landlord_Properties is empty in this workbook version (filled after the City MPROP / absentee-owner upload).

on conflict (pm_id) do update set company = excluded.company, focus = excluded.focus, address_listed = excluded.address_listed, source_ids = excluded.source_ids, landlord_id = excluded.landlord_id, import_version = excluded.import_version, imported_at = now();

on conflict (network_key) do update set rank = excluded.rank, owner_network = excluded.owner_network, parcels = excluded.parcels, units = excluded.units, flag = excluded.flag, source_id = excluded.source_id, landlord_id = excluded.landlord_id, import_version = excluded.import_version, imported_at = now();

on conflict (metric) do update set value = excluded.value, note = excluded.note, source_id = excluded.source_id, is_derived = excluded.is_derived, import_version = excluded.import_version, imported_at = now();

on conflict (source_id) do update set source = excluded.source, what_it_contains = excluded.what_it_contains, access = excluded.access, use_in_db = excluded.use_in_db, adopted = excluded.adopted, import_version = excluded.import_version, imported_at = now();

on conflict (id) do update set doc = excluded.doc, claim_or_item = excluded.claim_or_item, verdict = excluded.verdict, reason = excluded.reason, action_taken = excluded.action_taken, import_version = excluded.import_version, imported_at = now();

on conflict (step) do update set name = excluded.name, action = excluded.action, step_owner = excluded.step_owner, import_version = excluded.import_version, imported_at = now();
