insert into lrd_channels (channel_id, channel, what_it_is, contact_access, how_used, verification_status, source_ids, import_version) values
  ('CH01', 'City DNS Landlord Training Program', 'Free, year-round classes (virtual and live) for people operating rental property; DNS + Milwaukee Police', 'Registration: LLTP@milwaukee.gov, (414) 286-2954; live classes at Anderson Lake Tower, 4001 S 6th St, and library branches', 'Highest-yield source of small/new landlords. Ask DNS whether 2nd Chance can share a one-page partner flyer or table at sessions.', 'Verified – Current', 'L06;L07;L08', 'v0.2'),
  ('CH02', 'Rental Property Association of Wisconsin (RPA; formerly AASEW)', 'State''s largest landlord trade association; monthly meetings; RPA-CON conference; founded 1974; Landlord Boot Camp (twice yearly)', 'rpawi.org; admin@rpawi.org / membership@rpawi.org; (414) 276-7378; P.O. Box 4125, Milwaukee, WI 53204-7905 (also listed as 53226)', 'Sponsor/exhibit at RPA-CON (held Oct 16, 2026 – plan for 2027); present LIFT + 2nd Chance partnership at a member meeting.', 'Verified – Current', 'L10;L11;L12;L29;L30;L31;DOC-E', 'v0.2'),
  ('CH03', 'Milwaukee Real Estate Investors Association (Milwaukee REIA)', 'Monthly 2nd-Tuesday meetings (150+ attendees); 500+ active members with a Member Search Directory (2025 catalog; other directories say 200–550)', 'milwaukeereia.com; (414) 949-7342; meeting sites vary (Sonesta Wauwatosa, DoubleTree Brookfield)', 'Small investors buying 1–10 doors. Vendor table or short talk on guaranteed-rent/LIFT tenants.', 'Verified – Current', 'L10;L13;L32;L33;L34;DOC-E', 'v0.2'),
  ('CH04', 'Milwaukee County Landlord Outreach & Networking Events', 'County events on renting to returning citizens, featuring LIFT (Jul 28 & Aug 26, 2026)', 'Contact on flyer: Monique Malone, (414) 897-3397, Monique.Malone@milwaukeecountywi.gov', 'Co-host the next event; collect opt-in sign-ups from attending landlords.', 'Verified – Current', 'L09', 'v0.2'),
  ('CH05', 'Milwaukee County LIFT landlord network', '~96 landlords joined (Jan 2026); risk-mitigation guarantees for voucher/rent-assistance tenants', 'LIFTMKE.com; County Housing Services landlord engagement', 'List not public. Ask County for a partner referral path or joint outreach to LIFT members.', 'Verified – Current', 'L27', 'v0.2'),
  ('CH06', 'Rental Housing Resource Center landlord events', 'Landlord & Property Management Rental Application Event (Mar 11, 2026)', '728 N. James Lovell St.; 414-895-7368', 'Join as a housing-provider participant; landlords who attend are already open to assisted tenants.', 'Verified – Current', 'L14', 'v0.2'),
  ('CH07', 'MKEPropertyOwnership.com', 'Look up any rental address → owner network, all linked LLCs and properties', 'mkepropertyownership.com (free)', 'Use to de-duplicate LLCs and confirm portfolio size for any landlord you meet.', 'Verified – Current', 'L04;L05', 'v0.2'),
  ('CH08', 'Apartment Owners and Managers Association of Milwaukee (AOMA)', 'Directory claims 1,500 member landlords', 'Not verified', 'May be an older name for RPA/AASEW – confirm before outreach.', 'Unverified Lead', 'L28', 'v0.2'),
  ('CH09', 'Property management companies', 'Manage portfolios for many small owners (see Property_Managers)', 'See sheet', 'One PM relationship can unlock dozens of independent owners'' units.', 'Verified – Limited', 'L19;L20;L21', 'v0.2'),
  ('CH10', 'DNS Property Registration records', 'Owner/agent contact registrations searchable in City LMS (enforcement search)', 'city.milwaukee.gov/lms → Enforcement → Search Records', 'Public records; useful to find a local agent for out-of-state owners. Confirm current access.', 'Needs Confirmation', 'L25', 'v0.2'),
  ('CH11', 'Havenwoods Neighborhood Partnership – Annual Landlord Breakfast', 'Northwest-side BID hosts a yearly landlord breakfast (e.g., Feb 20, 2025 at Wisconsin Country Club)', '6161 N. 64th St., Milwaukee, WI 53218; (414) 431-2274 (BID office line)', 'Ask to present at the next breakfast; NW side has many small landlords.', 'Verified – Current', 'L35;L36;DOC-E', 'v0.2'),
  ('CH12', 'Neighborhood landlord compacts (e.g., Washington Park)', 'Landlords meet monthly with police, DNS and partners', 'Via neighborhood associations / DNS', 'Find which compacts are still active (2014 source).', 'Needs Confirmation', 'L37', 'v0.2'),
  ('CH13', 'KANDO (Kaul Avenue Neighborhood Development Organization)', 'Reported NW-side landlord compact led for 15+ years', 'neighborhoodlink.com (per Doc E)', 'No independent confirmation found this session.', 'Unverified Lead', 'DOC-E', 'v0.2'),
  ('CH14', 'Murray Hill Neighborhood Association', 'East Side association said to include landlords', 'murrayhillna.org (per Doc E)', 'Unconfirmed.', 'Unverified Lead', 'DOC-E', 'v0.2'),
  ('CH15', 'WiscoREIA', 'Statewide investor network listed with 3,000 members, weekly meetings', 'Not verified', 'Confirm before outreach.', 'Unverified Lead', 'L44', 'v0.2'),
  ('CH16', 'Greater Milwaukee Association of REALTORS (GMAR)', '~5,000 agent members; agents list rentals and serve small investors', '(414) 778-4929', 'Present at an agent meeting; agents refer owner-clients.', 'Verified – Limited', 'L45', 'v0.2'),
  ('CH17', 'HACM landlord leasing desk', 'Existing HCV landlords (~2,000)', 'section8leasing@hacm.org; (414) 286-5650', 'Ask HACM to share 2nd Chance info with landlords (list itself not public).', 'Verified – Limited', 'L43', 'v0.2')
insert into lrd_business_networks (network_id, network, who_belongs, contact, how_to_use, verification_status, source_url, import_version) values
  ('BO01', 'Wisconsin Fuel & Retail Association (WFRA; formerly WPMCA)', 'Independent fuel marketers and convenience-store owners statewide (300+ member companies)', '(608) 256-7555; wfra.org', 'Ask to place a housing-partnership notice in member communications or exhibit at the annual convention.', 'Verified – Limited', 'https://duck-gold-6a2c.squarespace.com/about', 'v0.2'),
  ('BO02', 'Wisconsin Grocers Association', 'Grocery retailers incl. independent stores; member e-newsletter and 2026 event calendar', 'wisconsingrocers.com', 'Member newsletter / event table.', 'Verified – Limited', 'https://wisconsingrocers.com/retail-membership/', 'v0.2'),
  ('BO03', 'Hispanic Chamber of Commerce of Wisconsin', 'Statewide business chamber (Walker''s Point HQ)', '1021 W. National Ave., Milwaukee, WI 53204; (414) 643-6963; hccw.org', 'Partner presentation; bilingual landlord info session.', 'Verified – Current', 'https://web.mmac.org/demo/Associations?xsort=true', 'v0.2'),
  ('BO04', 'African American Chamber of Commerce of Wisconsin', 'Statewide business chamber', '1920 N. Dr. Martin Luther King Jr. Dr., Milwaukee, WI 53212; (414) 462-9450; aaccwi.org', 'Member directory (ChamberMaster) lists businesses, not property – use for event outreach.', 'Verified – Current', 'https://web.mmac.org/Associations?xsort=true', 'v0.2'),
  ('BO05', 'Hmong Wisconsin Chamber of Commerce', 'Business chamber serving Asian and underinvested business communities', '5423 N. 118th Ct., Milwaukee, WI 53225; (414) 645-8828; hmongchamber.org', 'Partner presentation; translated landlord materials.', 'Verified – Current', 'https://web.mmac.org/demo/Associations', 'v0.2'),
  ('BO06', 'Wisconsin Chinese Chamber of Commerce', 'Business chamber', '6525 W. Bluemound Rd., Milwaukee, WI 53213; (414) 581-8844', 'Event outreach.', 'Verified – Limited', 'https://web.mmac.org/demo/Associations', 'v0.2'),
  ('BO07', 'American Indian Chamber of Commerce of Wisconsin / First American Capital Corp.', 'Business chamber and lender', '(414) 604-2044; aiccw-facc.org', 'Event outreach.', 'Verified – Limited', 'https://www.wisbank.com/partnering-with-wisconsins-diverse-small-businesses/', 'v0.2'),
  ('BO08', 'Wisconsin Veterans Chamber of Commerce', 'Veteran-owned business chamber', '5027 W. North Ave., Milwaukee, WI 53208; (414) 207-4376', 'Pair with veteran-housing (SSVF/VASH) landlord pitch.', 'Verified – Limited', 'https://web.mmac.org/demo/Associations', 'v0.2'),
  ('BO09', 'Wisconsin Black Chamber of Commerce; Ethnic & Diverse Business Coalition; Greater Milwaukee Chamber of Commerce', 'Additional business networks', 'twbcc.com; edbcwisconsin.org; gmcofc.org', 'Event outreach.', 'Verified – Limited', 'https://www.wispro.org/wp-content/uploads/2023/07/Final-Resource-Dir.pdf', 'v0.2'),
  ('BO10', 'Metropolitan Milwaukee Association of Commerce (MMAC) – associations directory', 'Regional chamber; directory of business/neighborhood associations and BIDs', 'mmac.org', 'Find neighborhood business associations near target rental areas.', 'Verified – Current', 'https://web.mmac.org/Associations?xsort=true', 'v0.2')
