insert into lrd_data_sources (source_id, source, what_it_contains, access, use_in_db, adopted, import_version) values
  ('L02', 'Absentee-owner mailing list (City)', 'Owner name + tax-bill mailing address for non-owner-occupied parcels', 'Free CSV download', 'PRIMARY INPUT – upload here and run build_landlord_db.py', true, 'v0.2'),
  ('L01', 'MPROP (City)', '~160,000 parcels; owner, mailing address, units, land use, owner-occupied flag', 'Free CSV download (daily updates)', 'Alternative primary input; richer (units, land use)', true, 'v0.2'),
  ('L04', 'MKEPropertyOwnership.com + GitHub raw data', 'Linked LLC ownership networks, eviction & code-violation rates', 'Free (public repo jdjohn215/mke-owner-networks)', 'Use to merge LLCs into one landlord; GitHub blocked from this workspace – upload network CSV if wanted', true, 'v0.2'),
  ('L26', 'Wisconsin Statewide Parcels (UW SCO)', 'Owner name + full mailing address statewide (incl. suburbs)', 'Free download', 'Extend beyond City to Milwaukee County suburbs', true, 'v0.2'),
  ('WI DFI', 'Wisconsin DFI corporate records search', 'Registered agent & principal office for LLCs', 'Free web lookup (wdfi.org)', 'Find a business contact for LLC landlords', true, 'v0.2'),
  ('WI DSPS', 'Wisconsin DSPS license lookup', 'Licensed real estate brokers (WI property managers generally need a broker license)', 'Free web lookup', 'Verify property managers', true, 'v0.2'),
  ('L25', 'DNS LMS enforcement / property registration', 'Registered owner/agent contacts', 'Free web search', 'Local agents for out-of-state owners', true, 'v0.2'),
  ('CCAP', 'Wisconsin Circuit Court Access (CCAP)', 'Eviction plaintiffs (landlord names)', 'Free, but terms limit bulk use', 'Do not bulk-scrape; use only for case-by-case due diligence', true, 'v0.2'),
  ('Listings', 'Zillow / Apartments.com / Craigslist / Facebook Marketplace', 'Active rental listings with landlord contact', 'Terms prohibit scraping', 'Manual only: call listings that say ''Section 8 OK''; log opt-in contacts', true, 'v0.2'),
  ('network-components.csv', 'MKEPropertyOwnership GitHub network file (6.1 MB per Doc E)', 'Owner names/mailing addresses already linked into landlord networks', 'Free: github.com/jdjohn215/mke-owner-networks/raw/refs/heads/main/data/network-components.csv', 'BEST SECOND UPLOAD – lets us merge LLCs into one landlord; blocked from this workspace, so download and attach', true, 'v0.2'),
  ('L38', 'MKE Evict (eviction filings by landlord)', 'Eviction filing history by owner/LLC', 'Free web', 'SCREENING ONLY – check a landlord before referring tenants; not an outreach target list', true, 'v0.2'),
  ('L39', 'Eviction Lab – Milwaukee top filers', 'Largest eviction filers', 'Free download', 'SCREENING ONLY', true, 'v0.2'),
  ('L40', 'MKEPropertyOwnership network pages', 'Network-level code-violation and eviction rates', 'Free web', 'SCREENING – fill screening columns in Landlord_Records', true, 'v0.2'),
  ('Tax delinquency', 'City Treasurer delinquent-tax lists (Doc E)', 'Owners behind on taxes', 'Public', 'NOT ADOPTED for targeting – reaching distressed owners is not a fit for tenant placement; use only as a risk flag', false, 'v0.2'),
  ('Skip tracing', 'Paid phone/e-mail append (Doc E)', 'Personal phones/e-mails of individual owners', 'Paid', 'NOT ADOPTED – database adds contact details only when a landlord opts in', false, 'v0.2'),
  ('Alcohol licenses', 'City Valid Alcohol License Report (Doc F)', 'Business licensees/agents', 'Free PDF', 'NOT ADOPTED as a landlord source – license agents are not property owners; property records identify landlords directly', false, 'v0.2')
insert into lrd_gap_analysis (id, doc, claim_or_item, verdict, reason, action_taken, import_version) values
  (1, 'E', 'Core method: MPROP + owner networks; ~71% of networks own one property', 'Adopt', 'Matches v0.1 (L03).', 'No change; numbers updated to Nov 2026 vintage (Doc E used older counts: 19,849 networks / 14,171 single).', 'v0.2'),
  (2, 'E', 'Network file network-components.csv on GitHub', 'Adopt', 'Saves rebuilding LLC links.', 'Added to Data_Sources as second upload; workspace cannot download GitHub.', 'v0.2'),
  (3, 'E', 'MPROP field names OWNER_MAILING_ADDR / OWNER_OCCUPIED Y/N / LAND_USE ''contains Rental''', 'Adopt with change', 'MPROP land use is numeric (88xx residential); field names vary by file.', 'build_landlord_db.py now accepts these names too; land-use filter stays numeric.', 'v0.2'),
  (4, 'E', '''wget https://data.milwaukee.gov/dataset/mprop''', 'Correct', 'That URL is the dataset page, not the CSV.', 'Build_Steps tells you to click CSV → Download.', 'v0.2'),
  (5, 'E', 'RPA contacts (rpawi.org, membership email, 414-276-7378)', 'Adopt', 'Verified on RPA pages; founded 1974.', 'CH02 updated.', 'v0.2'),
  (6, 'E', 'Milwaukee REIA: (414) 949-7342; 550+ members', 'Adopt with change', 'Phone verified; member count varies by source (200–550; 2025 catalog says 500+).', 'CH03 updated with range.', 'v0.2'),
  (7, 'E', 'KANDO, Havenwoods landlord breakfasts, Murray Hill NA', 'Partly adopt', 'Havenwoods breakfast verified; KANDO and Murray Hill not confirmed.', 'Added CH11 (verified), CH13–CH14 (unverified), plus CH12 Washington Park compacts.', 'v0.2'),
  (8, 'E', '10 additional property managers', 'Adopt as leads', 'From BBB/web per Doc E; not re-checked. Anchor Property Management needs screening (possible link to Hoff-era ''Anchor Properties'').', 'Added PM16–PM24; Welcome Home address/phone added.', 'v0.2'),
  (9, 'E', 'Rental listing sites (HotPads, Craigslist, ForRent FRBO)', 'Adopt with change', 'Site terms bar scraping.', 'Manual use only: respond to ''by owner'' listings and log opt-ins.', 'v0.2'),
  (10, 'E', 'Target landlords with evictions, code violations, tax delinquency', 'Reject as targeting; adopt as screening', 'Partnering with high-eviction or neglectful owners puts tenants at risk; tax-distressed owners are a poor fit.', 'Added screening columns (eviction/code-violation rates) and a Do-Not-Partner flag; Highgrove added as example.', 'v0.2'),
  (11, 'E', 'Skip tracing for phones/e-mails', 'Reject', 'Database policy: contact details only when a landlord opts in; avoids TCPA/DNC exposure.', 'Listed as ''Not adopted'' in Data_Sources.', 'v0.2'),
  (12, 'E', 'Request Landlord Training graduate list from DNS', 'Adopt (ask)', 'City decides what it can share; email in Doc E (llfp@) differs from verified LLTP@milwaukee.gov.', 'CH01 keeps verified contact.', 'v0.2'),
  (13, 'E', 'Schema: landlords / landlord_properties / landlord_interactions', 'Adopt', 'Fills a v0.1 gap (no properties table).', 'Added Landlord_Properties sheet; Outreach_Log = interactions.', 'v0.2'),
  (14, 'F', 'Premise: gas, grocery and ''ethnic restaurant'' owners are disproportionately immigrants who hold real estate', 'Reject', 'Selecting people by ethnicity or national origin is not a fair or accurate way to find landlords and could raise fair-housing concerns.', 'No individuals from Doc F imported.', 'v0.2'),
  (15, 'F', '62 named owners/agents with phone numbers from alcohol-license records', 'Reject', 'License agents are not necessarily property owners; this compiles personal details on private people without a landlord link.', 'Not imported. Any of them who own rentals will appear through the property-records pipeline, same as every other owner.', 'v0.2'),
  (16, 'F', 'Surname matching (e.g., ''Singh'' across licenses implies one family network)', 'Reject', 'Common surnames link unrelated people – produces false matches.', 'Pipeline matches on exact owner name + tax-bill mailing address only.', 'v0.2'),
  (17, 'F', 'Match on mailing address rather than names', 'Adopt', 'More reliable than name matching.', 'Already the method in build_landlord_db.py.', 'v0.2'),
  (18, 'F', 'WDFI registered agents; CCAP for due diligence', 'Adopt (already in v0.1)', '—', 'No change.', 'v0.2'),
  (19, 'F', 'Paid lead lists (store/restaurant e-mail lists)', 'Reject', 'Not landlord data; unverified consent.', 'Not adopted.', 'v0.2'),
  (20, 'F', 'Ethnic chambers'' member directories as lead lists', 'Adopt with change', 'Chambers are good outreach venues; directories are business listings, not landlords.', 'Kept Business_Owner_Networks for presentations/events, open to all owners.', 'v0.2'),
  (21, 'v0.1 gap', 'No screening for landlord quality', 'Fixed', 'Needed before referring tenants.', 'Screening columns + Do-Not-Partner flag added.', 'v0.2'),
  (22, 'v0.1 gap', 'No properties table', 'Fixed', 'Relational design.', 'Landlord_Properties sheet added.', 'v0.2')
insert into lrd_build_steps (step, name, action, step_owner, import_version) values
  (1, 'Download', 'Go to data.milwaukee.gov → ''CityPropertyMailingListOwnerAbsentee'' (or ''Master Property File (MPROP)'') → CSV → Download.', 'You (2 minutes)', 'v0.2'),
  (2, 'Upload', 'Attach the CSV in this chat.', 'You', 'v0.2'),
  (3, 'Build', 'I run build_landlord_db.py: keep rentals, group parcels by owner + tax-bill address, tag entity type, local vs out-of-state, size tier, independent flag.', 'Claude', 'v0.2'),
  (4, 'Link LLCs', 'Merge LLCs that share tax-bill/registered addresses (MKEPropertyOwnership method) so each landlord = one record.', 'Claude', 'v0.2'),
  (5, 'Prioritize', 'Score: independent (≤25 units), local mailing address, units in target neighborhoods, LIFT/voucher-friendly signals.', 'Claude + 2nd Chance', 'v0.2'),
